/**
 * Deactivates the account (accountType-appropriate students.edit / parents.edit permission required). Idempotent — a redundant call on an already-deactivated account returns 200 with no additional audit event. Notification devices are deactivated as part of this action.
 */
export const DeactivateStudentParams = zod.object({
  id: zod.coerce.number(),
});

export const deactivateStudentBodyReasonMax = 500;

export const DeactivateStudentBody = zod.object({
  reason: zod.string().max(deactivateStudentBodyReasonMax).optional(),
});

export const DeactivateStudentResponse = zod.object({
  id: zod.number(),
  accountStatus: zod.enum(["active", "deactivated"]),
});

/**
 * Reactivates a deactivated account (accountType-appropriate students.edit / parents.edit permission required). Idempotent — a redundant call on an already-active account returns 200 with no additional audit event. Notification devices disabled at deactivation time are NOT restored; a fresh login/device registration is required.
 */
export const ReactivateStudentParams = zod.object({
  id: zod.coerce.number(),
});

export const ReactivateStudentResponse = zod.object({
  id: zod.number(),
  accountStatus: zod.enum(["active", "deactivated"]),
});

/**
 * Phase B3B0-2: starts (or, if already active, idempotently re-returns) an administrative deletion-preparation freeze workflow for an already-deactivated Student account. Requires users.delete. Not a permanent delete — no data is removed or anonymized. Orthogonal to accountStatus: while a preparation is PREPARING, identity-changing email PATCHes and Reactivate are both rejected with 409 STUDENT_DELETION_PREPARATION_ACTIVE. Only non-sensitive workflow metadata is returned or stored — no raw email, provenance fingerprint, secret material, child PII, or financial detail.
 */
export const StartStudentDeletionPreparationParams = zod.object({
  id: zod.coerce.number(),
});

export const StartStudentDeletionPreparationResponse = zod
  .object({
    id: zod.number(),
    studentId: zod.number().optional(),
    status: zod.enum(["PREPARING", "CANCELLED"]),
    active: zod.boolean().optional(),
    startedAt: zod.coerce.date().nullish(),
    cancelledAt: zod.coerce.date().nullish(),
    policyVersion: zod.string().optional(),
  })
  .describe(
    'Phase B3B0-2 workflow metadata only. `id` is the workflow row id on the started\/cancelled\/already-active branches; on the \"no active preparation to cancel\" idempotent branch `id` is the studentId and `active: false` is returned instead. No raw email, provenance fingerprint, secret material, child PII, or financial detail is ever present in this shape.',
  );

/**
 * Phase B3B0-2: cancels the active deletion-preparation workflow for a Student, if one exists. Requires users.delete. Idempotent — if no preparation is currently active, returns 200 with active: false and produces no state change or audit event. Cancelling does NOT reactivate the account; accountStatus remains deactivated and a separate explicit Reactivate call is required. After cancellation, email identity changes become available again.
 */
export const CancelStudentDeletionPreparationParams = zod.object({
  id: zod.coerce.number(),
});

export const CancelStudentDeletionPreparationResponse = zod
  .object({
    id: zod.number(),
    studentId: zod.number().optional(),
    status: zod.enum(["PREPARING", "CANCELLED"]),
    active: zod.boolean().optional(),
    startedAt: zod.coerce.date().nullish(),
    cancelledAt: zod.coerce.date().nullish(),
    policyVersion: zod.string().optional(),
  })
  .describe(
    'Phase B3B0-2 workflow metadata only. `id` is the workflow row id on the started\/cancelled\/already-active branches; on the \"no active preparation to cancel\" idempotent branch `id` is the studentId and `active: false` is returned instead. No raw email, provenance fingerprint, secret material, child PII, or financial detail is ever present in this shape.',
  );

/**
 * Phase B2B: read-only deletion impact analysis for permanent Student account deletion. Requires users.delete. Truly read-only — no audit row, no Student mutation, no OTP/device mutation is ever produced by this call. Advisory only: `canDelete`/`blockers` reflect current-state information as of `generatedAt` under `policyVersion`; a future Permanent Delete execution MUST recompute the full blocker set inside its own locked transaction and must never trust a client-supplied deletion state (this GET has no request body).
 */
export const GetStudentDeletionImpactParams = zod.object({
  id: zod.coerce.number(),
});

export const GetStudentDeletionImpactResponse = zod
  .object({
    studentId: zod.number(),
    lifecycleStatus: zod.enum(["active", "deactivated", "deleted"]),
    canDelete: zod.boolean(),
    generatedAt: zod.coerce.date(),
    policyVersion: zod.string(),
    blockers: zod.array(
      zod.object({
        key: zod.enum([
          "ACCOUNT_MUST_BE_DEACTIVATED",
          "FUTURE_BOOKINGS",
          "PENDING_BOOKING_PAYMENT",
          "ACTIVE_PACKAGE_VALUE",
          "PENDING_PACKAGE_ORDER",
          "OPEN_REFUND",
          "ACTIVE_BALLET_ENROLLMENT",
          "OPEN_BALLET_APPLICATION",
          "PENDING_BALLET_PAYMENT",
          "OPEN_BALLET_CANCELLATION_REVIEW",
          "CHILD_FUTURE_COMMITMENT",
          "AMBIGUOUS_LEGACY_ATTRIBUTION",
          "LEGACY_IDENTITY_BACKFILL_REQUIRED",
        ]),
        label: zod.string(),
        description: zod.string(),
        count: zod.number().optional(),
      }),
    ),
    categories: zod.array(
      zod.object({
        key: zod.string(),
        label: zod.string(),
        classification: zod.enum(["delete", "anonymize", "retain", "blocker"]),
      }),
    ),
    deletionPreparation: zod
      .object({
        active: zod.boolean(),
        startedAt: zod.coerce.date().nullable(),
        status: zod
          .union([
            zod.literal("PREPARING"),
            zod.literal("CANCELLED"),
            zod.literal(null),
          ])
          .nullable(),
        workflowId: zod
          .number()
          .nullable()
          .describe(
            "Phase B3B4 additive extension. The active workflow id, for submitting POST \/permanent-delete's required workflowId. null when no preparation is active.",
          ),
      })
      .describe(
        "Phase B3B0-2 additive extension. Read-only status surface — this GET performs no writes. Does not add a Permanent Delete capability; canDelete\/blockers semantics above are unchanged.",
      ),
    manualResolution: zod
      .object({
        requiredCount: zod.number(),
        resolvedOwnerCount: zod.number(),
        resolvedNotThisStudentCount: zod.number(),
        unresolvedCount: zod.number(),
        conflictCount: zod
          .number()
          .describe(
            "Candidates whose channel-B provenance and channel-C independent evidence point at different students. These are fail-closed: they are ALSO included in requiredCount and unresolvedCount, and no decision of any kind can be recorded for them.",
          ),
      })
      .describe(
        "Phase B3B2E aggregate block summary for Level-B manual resolution. Counts only — no row identifiers or evidence detail. Any candidate counted in `unresolvedCount` blocks permanent deletion.",
      ),
    summary: zod.object({
      bookings: zod.object({
        historical: zod.number(),
        future: zod.number(),
      }),
      payments: zod.object({
        completed: zod.number(),
        pending: zod.number(),
        openRefunds: zod.number(),
      }),
      packages: zod.object({
        active: zod.number(),
        expired: zod.number(),
        unusedCredits: zod.number(),
        pendingOrders: zod.number(),
      }),
      children: zod.object({
        total: zod.number(),
        withFutureActivity: zod.number(),
      }),
      ballet: zod.object({
        applicationsOpen: zod.number(),
        applicationsTerminal: zod.number(),
        enrollmentsActive: zod.number(),
        paymentsPending: zod.number(),
        refundsOpen: zod.number(),
        cancellationsPendingReview: zod.number(),
      }),
      security: zod.object({
        devices: zod.number(),
        otpChallenges: zod.number(),
        providerLinks: zod.number(),
      }),
      legacyAttribution: zod.object({
        emailOnlyRows: zod.number(),
        ambiguousRows: zod.number(),
      }),
    }),
  })
  .describe(
    "Advisory-only deletion impact analysis. Not a concurrency token, not a signed confirmation token — see policyVersion\/generatedAt notes on the parent operation.",
  );

/**
 * Phase B3B1: read-only historical attribution planner for permanent Student account deletion. Requires users.delete. Zero writes — a plain, transactional SELECT. Only produces an authoritative plan while the Student has an active (PREPARING) deletion-preparation workflow; otherwise returns 409 STUDENT_DELETION_PREPARATION_REQUIRED. There is no preview/execution mode — this endpoint never mutates ownership or identity data.
 */
export const GetStudentDeletionAttributionPlanParams = zod.object({
  id: zod.coerce.number(),
});

export const GetStudentDeletionAttributionPlanResponse = zod
  .object({
    studentId: zod.number(),
    workflowId: zod.number(),
    preparationStatus: zod.enum(["PREPARING"]),
    generatedAt: zod.coerce.date(),
    policyVersion: zod.string(),
    provenanceActivationReference: zod.coerce.date().nullable(),
    summary: zod.object({
      alreadyAttributed: zod.number(),
      safeToAttribute: zod.number(),
      ambiguous: zod.number(),
      unproven: zod.number(),
      nonAttributable: zod.number(),
    }),
    domains: zod.array(
      zod.object({
        domain: zod.enum(["bookings", "package_orders", "feedback"]),
        classification: zod.enum([
          "ALREADY_ATTRIBUTED",
          "SAFE_TO_ATTRIBUTE",
          "UNPROVEN_PRE_T0",
          "AMBIGUOUS_PROVENANCE",
          "NO_MATCH",
          "SEMANTICALLY_NOT_STUDENT_OWNERSHIP",
          "MISSING_REQUIRED_TIMESTAMP",
          "MALFORMED_LEGACY_IDENTITY",
          "INDEPENDENT_LEVEL_B_EVIDENCE",
          "EVIDENCE_CONFLICT",
        ]),
        count: zod.number(),
        reasonCode: zod.string(),
        executionEligible: zod.boolean(),
      }),
    ),
    levelBResolutions: zod
      .array(
        zod.object({
          domain: zod.enum(["package_orders"]),
          targetRecordId: zod.number(),
          resolutionStatus: zod
            .enum(["NONE", "PROVEN_OWNER", "NOT_THIS_STUDENT", "UNRESOLVED"])
            .describe(
              "Latest durable append-only decision for this candidate. NONE means no decision has ever been recorded. NONE and UNRESOLVED both block permanent deletion.",
            ),
        }),
      )
      .describe(
        "Phase B3B2E additive extension. Per-candidate Level-B manual resolution status for the resolvable subset of the canonical package_orders candidate universe. A candidate whose channel-B provenance and channel-C independent evidence disagree (EVIDENCE_CONFLICT) is deliberately NOT listed here — it is not resolvable, and is visible only as an aggregate count in `domains` and in the deletion-impact `manualResolution` summary. Contains internal record ids only — no raw email, no provenance fingerprint, no payment detail, no child PII.",
      ),
  })
  .describe(
    "Phase B3B1: read-only historical attribution plan. Zero writes. Aggregate\/count-only — no row-level identifiers, no raw email, no fingerprint ever appear here. Only produced while an active (PREPARING) deletion-preparation workflow exists for this Student.",
  );

/**
 * Phase B3B2E: records a durable, append-only Level-B manual resolution decision for one unattributed package_orders candidate. Requires users.delete. LEVEL-B ONLY — the server independently re-derives Level-B evidence inside the same transaction as the insert and never trusts any client evidence claim. This writes an authorization/evidence decision row ONLY; it never writes any canonical ownership column, so no historical record ownership is changed. Requires the Student to be deactivated with an active deletion preparation. A candidate in EVIDENCE_CONFLICT is fail-closed and rejects every decision, including UNRESOLVED.
 */
export const RecordStudentDeletionManualResolutionParams = zod.object({
  id: zod.coerce.number(),
});

export const RecordStudentDeletionManualResolutionBody = zod
  .object({
    workflowId: zod.number(),
    domain: zod.enum(["package_orders"]),
    targetRecordId: zod.number(),
    decision: zod.enum(["PROVEN_OWNER", "NOT_THIS_STUDENT", "UNRESOLVED"]),
  })
  .describe(
    "No free-text field is accepted by design — the server derives and stores the evidence reason code itself and never persists an admin-authored evidence narrative.",
  );

export const RecordStudentDeletionManualResolutionResponse = zod
  .object({
    id: zod.number(),
    studentId: zod.number(),
    domain: zod.enum(["package_orders"]),
    targetRecordId: zod.number(),
    deletionWorkflowId: zod.number(),
    evidenceLevel: zod.string(),
    decision: zod.enum(["PROVEN_OWNER", "NOT_THIS_STUDENT", "UNRESOLVED"]),
    evidenceReasonCode: zod.string(),
    resolvedAt: zod.coerce.date(),
  })
  .describe(
    "The durable, append-only decision row that was created. Recording a PROVEN_OWNER decision does NOT rewrite any canonical ownership column — no historical record ownership is changed by this call.",
  );

/**
 * Phase B3B3: applies every currently eligible PROVEN_OWNER Level-B resolution for this Student by populating the canonical historical ownership FK (package_orders.student_id). Requires users.delete. package_orders is the ONLY supported domain — it is the only one with an independent Level-B evidence source. Every precondition (Student exists, deactivated, active preparation, workflow current, decision still PROVEN_OWNER and not superseded, target still a canonical candidate, Level-B evidence still valid, no evidence conflict, ownership FK still NULL) is re-validated fresh inside the applying transaction under row locks; anything stale fails closed. This endpoint NEVER deletes, anonymizes or tombstones a Student account, never touches Level C/D rows, never rewrites a historical snapshot (legacy email, payer contact, amounts, payment data, credit_transactions, attendance, provenance), and never mutates the append-only resolution history. Repeated and concurrent execution is safe and idempotent.
 */
export const ApplyStudentDeletionOwnershipBackfillParams = zod.object({
  id: zod.coerce.number(),
});

export const ApplyStudentDeletionOwnershipBackfillBody = zod
  .object({
    workflowId: zod.number(),
  })
  .describe(
    "Phase B3B3. Carries NO ownership data by design — only the workflow id, used for staleness matching against the Student's currently active deletion preparation. Target ids, owner ids and evidence are all re-derived server-side inside the applying transaction, so a client can never nominate a record or an owner.",
  );

export const ApplyStudentDeletionOwnershipBackfillResponse = zod
  .object({
    studentId: zod.number(),
    workflowId: zod.number(),
    appliedCount: zod.number(),
    alreadyAppliedCount: zod.number(),
    results: zod.array(
      zod.object({
        domain: zod.enum(["package_orders"]),
        targetRecordId: zod.number(),
        action: zod
          .enum(["APPLIED", "ALREADY_APPLIED"])
          .describe(
            "APPLIED — the canonical ownership FK was NULL and now points at this Student. ALREADY_APPLIED — it already pointed at this Student (idempotent no-op, not an error).",
          ),
        resolutionId: zod.number().nullable(),
      }),
    ),
  })
  .describe(
    "Outcome of applying every currently eligible PROVEN_OWNER decision. The ONLY mutation performed is populating the canonical historical ownership FK (package_orders.student_id). No Student account is deleted, anonymized or tombstoned, no historical snapshot column is rewritten, and the append-only resolution history is untouched.",
  );

/**
 * Phase B3B4: the terminal Student account-lifecycle transition. account_status becomes "deleted" (the Student row is never physically removed — this is a tombstone, not a hard delete); Student PII (email, name, phone, password hash, social provider identifiers, avatar, profile fields) is anonymized on the same row; every outstanding JWT is invalidated (token_version bump); active notification devices are deactivated. Requires users.delete. Every precondition (Student exists, deactivated, active preparation current, the full deletion-impact blocker set recomputed fresh including unresolved Level-B / EVIDENCE_CONFLICT, and zero pending PROVEN_OWNER decisions not yet applied via the ownership-backfill executor) is re-validated inside one locked transaction; a client-supplied eligibility snapshot is never trusted. Historical rows (bookings/package_orders/feedback, credit_transactions, attendance, payment_records, provenance history) are completely untouched — an owned row's ownership FK keeps pointing at the now-tombstoned Student id, and Level C/D legacy rows are never assigned. Repeated execution against an already-deleted Student is a stable idempotent success, not an error.
 */
export const ApplyStudentPermanentDeleteParams = zod.object({
  id: zod.coerce.number(),
});

export const ApplyStudentPermanentDeleteBody = zod
  .object({
    workflowId: zod.number(),
  })
  .describe(
    "Phase B3B4. Carries no PII and no eligibility claim — only the workflow id, used for staleness matching against the Student's currently active deletion preparation. The full blocker set is re-derived server-side inside the applying transaction.",
  );

export const ApplyStudentPermanentDeleteResponse = zod
  .object({
    id: zod.number(),
    accountStatus: zod.enum(["deleted"]),
    deletedAt: zod.string().nullable(),
    alreadyDeleted: zod
      .boolean()
      .describe(
        "true if this call found the Student already deleted (idempotent, no new mutation performed); false if this call performed the real transition.",
      ),
  })
  .describe(
    'Outcome of the terminal tombstone transition. The Student row still exists; account_status is now \"deleted\".',
  );

